INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('green-bowl','{"id":"green-bowl","title":"Боул с курицей и киноа","description":"Сочное филе, рассыпчатая киноа и свежие овощи. Всё, что нужно для неспешного обеда.","category":"Обеды","image":"/images/bowl.jpg","time":30,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"chicken","quantity":300},{"productId":"quinoa","quantity":120},{"productId":"avocado","quantity":100},{"productId":"tomato","quantity":160},{"productId":"cucumber","quantity":120},{"productId":"lettuce","quantity":40},{"productId":"oil","quantity":15},{"productId":"lemon","quantity":20},{"productId":"salt","quantity":2}],"steps":[{"text":"Промойте киноа и залейте водой в пропорции 1:2. Доведите до кипения, варите под крышкой на слабом огне.","minutes":15},{"text":"Нарежьте филе, посолите и обжарьте с половиной масла. Доведите до полной готовности: температура внутри самого толстого кусочка должна достигнуть 74 °C.","minutes":12},{"text":"Нарежьте овощи и авокадо. Разложите киноа, салат и курицу по мискам."},{"text":"Смешайте оставшееся масло с лимонным соком. Полейте боулы перед подачей."}],"tags":["Много белка","Без глютена","Без молока"],"source":"editorial","version":1}',0);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('avocado-toast','{"id":"avocado-toast","title":"Тост с авокадо и яйцом","description":"Хрустящий хлеб, нежное авокадо и яйцо — маленький ритуал хорошего утра.","category":"Завтраки","image":"/images/toast.jpg","time":15,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"bread","quantity":120},{"productId":"avocado","quantity":140},{"productId":"egg","quantity":2},{"productId":"tomato","quantity":100},{"productId":"lemon","quantity":10},{"productId":"salt","quantity":1}],"steps":[{"text":"Отварите яйца до полностью плотного белка и желтка.","minutes":10},{"text":"Подрумяньте хлеб на сухой сковороде. Разомните авокадо с лимонным соком и солью."},{"text":"Намажьте авокадо на тосты, добавьте нарезанные яйца и помидоры."}],"tags":["Быстро","Без мяса","Без молока"],"source":"editorial","version":1}',1);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('salmon-rice','{"id":"salmon-rice","title":"Лосось с рисом и брокколи","description":"Простой ужин с лимоном и овощами, который почти готовится сам.","category":"Ужины","image":"/images/salmon.jpg","time":30,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"salmon","quantity":300},{"productId":"rice","quantity":120},{"productId":"broccoli","quantity":250},{"productId":"lemon","quantity":40},{"productId":"oil","quantity":10},{"productId":"salt","quantity":2}],"steps":[{"text":"Промойте рис и сварите по инструкции на упаковке.","minutes":18},{"text":"Лосось посолите, добавьте лимон и масло. Запекайте при 190 °C до 63 °C внутри рыбы.","minutes":18},{"text":"Брокколи приготовьте на пару до мягкости.","minutes":7},{"text":"Разложите по тарелкам и полейте соком от запекания."}],"tags":["Много белка","Без глютена","Без молока"],"source":"editorial","version":1}',2);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('tomato-pasta','{"id":"tomato-pasta","title":"Паста с томатами и сыром","description":"Тот самый домашний вкус: сочные томаты, чеснок и немного хорошего сыра.","category":"Обеды","image":"/images/pasta.jpg","time":25,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"pasta","quantity":160},{"productId":"tomato","quantity":350},{"productId":"cheese","quantity":40},{"productId":"garlic","quantity":8},{"productId":"oil","quantity":15},{"productId":"salt","quantity":2}],"steps":[{"text":"Отварите пасту до готовности по инструкции. Сохраните немного воды от варки.","minutes":10},{"text":"Измельчите чеснок, прогрейте с маслом, добавьте нарезанные помидоры. Тушите на среднем огне.","minutes":12},{"text":"Соедините пасту с соусом. Добавьте немного воды от варки и тёртый сыр."}],"tags":["Без мяса","На каждый день"],"source":"editorial","version":1}',3);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('berry-oats','{"id":"berry-oats","title":"Овсянка с ягодами и орехами","description":"Тёплая сливочная овсянка со свежими ягодами и ложкой мёда.","category":"Завтраки","image":"/images/oats.jpg","time":12,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"oats","quantity":100},{"productId":"milk","quantity":300},{"productId":"water","quantity":150},{"productId":"berries","quantity":120},{"productId":"nuts","quantity":20},{"productId":"honey","quantity":15}],"steps":[{"text":"Залейте хлопья молоком и водой, варите на слабом огне, помешивая.","minutes":7},{"text":"Оставьте под крышкой на пару минут. Добавьте ягоды, орехи и мёд."}],"tags":["Быстро","Без мяса"],"source":"editorial","version":1}',4);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('greek-salad','{"id":"greek-salad","title":"Греческий салат","description":"Хрустящие овощи и солоноватая фета — свежесть в каждой вилке.","category":"Салаты и боулы","image":"/images/salad.jpg","time":15,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"tomato","quantity":250},{"productId":"cucumber","quantity":200},{"productId":"pepper","quantity":120},{"productId":"feta","quantity":100},{"productId":"onion","quantity":40},{"productId":"oil","quantity":15},{"productId":"lemon","quantity":15}],"steps":[{"text":"Нарежьте овощи крупными кусочками, лук — тонкими полукольцами."},{"text":"Смешайте овощи с маслом и лимонным соком. Сверху разложите фету."}],"tags":["Без мяса","Без глютена","Быстро"],"source":"editorial","version":1}',5);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('pumpkin-soup','{"id":"pumpkin-soup","title":"Крем-суп из тыквы","description":"Бархатистый, согревающий и совсем простой. Для прохладных дней.","category":"Супы","image":"/images/soup.jpg","time":35,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"pumpkin","quantity":500},{"productId":"carrot","quantity":100},{"productId":"onion","quantity":70},{"productId":"potato","quantity":150},{"productId":"oil","quantity":15},{"productId":"water","quantity":650},{"productId":"salt","quantity":3}],"steps":[{"text":"Нарежьте овощи. В кастрюле прогрейте лук с маслом, добавьте морковь и тыкву.","minutes":5},{"text":"Добавьте картофель и воду. Варите до полной мягкости овощей.","minutes":22},{"text":"Посолите, снимите с огня и измельчите погружным блендером. Будьте осторожны с горячим супом."}],"tags":["Без мяса","Без молока","Без глютена","Лёгкое"],"source":"editorial","version":1}',6);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('cottage-pancakes','{"id":"cottage-pancakes","title":"Нежные сырники","description":"Золотистая корочка и мягкая творожная серединка. Подавайте с ягодами.","category":"Завтраки","image":"/images/pancakes.jpg","time":25,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"cottage","quantity":350},{"productId":"egg","quantity":1},{"productId":"flour","quantity":50},{"productId":"honey","quantity":20},{"productId":"oil","quantity":10},{"productId":"berries","quantity":100}],"steps":[{"text":"Разомните творог с яйцом, мукой и мёдом. Сформируйте небольшие сырники."},{"text":"Обжарьте на небольшом огне под крышкой до плотной середины и золотистой корочки с двух сторон.","minutes":14},{"text":"Подавайте с ягодами."}],"tags":["Без мяса","Много белка"],"source":"editorial","version":1}',7);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('chicken-buckwheat','{"id":"chicken-buckwheat","title":"Гречка с курицей и грибами","description":"Уютный обед на одной сковороде. Просто, сытно и без лишней посуды.","category":"Основные блюда","image":"/images/chicken.jpg","time":35,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"buckwheat","quantity":140},{"productId":"chicken","quantity":300},{"productId":"mushroom","quantity":200},{"productId":"onion","quantity":70},{"productId":"carrot","quantity":80},{"productId":"oil","quantity":15},{"productId":"water","quantity":320},{"productId":"salt","quantity":3}],"steps":[{"text":"Нарежьте лук, грибы и морковь, обжарьте с маслом.","minutes":7},{"text":"Добавьте кусочки курицы и промытую гречку, залейте водой. Готовьте под крышкой до впитывания воды и 74 °C внутри курицы.","minutes":22},{"text":"Перемешайте и оставьте под крышкой на 5 минут."}],"tags":["Без глютена","Без молока","Много белка"],"source":"editorial","version":1}',8);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('chickpea-salad','{"id":"chickpea-salad","title":"Боул с нутом и овощами","description":"Растительный обед с нежным нутом и лимонной заправкой.","category":"Салаты и боулы","image":"/images/salad.jpg","time":15,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"chickpeas","quantity":300},{"productId":"tomato","quantity":200},{"productId":"cucumber","quantity":160},{"productId":"lettuce","quantity":60},{"productId":"oil","quantity":15},{"productId":"lemon","quantity":25}],"steps":[{"text":"Промойте готовый нут. Нарежьте помидоры и огурцы."},{"text":"Смешайте овощи, нут и салат. Заправьте маслом и соком лимона."}],"tags":["Без мяса","Без молока","Без глютена","Быстро"],"source":"editorial","version":1}',9);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('lentil-soup','{"id":"lentil-soup","title":"Чечевичный суп","description":"Густой овощной суп с красной чечевицей. Хорош и на следующий день.","category":"Супы","image":"/images/soup.jpg","time":35,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"lentils","quantity":140},{"productId":"carrot","quantity":100},{"productId":"onion","quantity":70},{"productId":"tomato","quantity":180},{"productId":"oil","quantity":12},{"productId":"water","quantity":800},{"productId":"salt","quantity":3}],"steps":[{"text":"Нарежьте лук и морковь, прогрейте в кастрюле с маслом.","minutes":5},{"text":"Добавьте промытую чечевицу, томаты и воду. Варите до мягкости чечевицы.","minutes":25},{"text":"Посолите. При желании частично измельчите блендером."}],"tags":["Без мяса","Без молока","Без глютена"],"source":"editorial","version":1}',10);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('vegetable-omelet','{"id":"vegetable-omelet","title":"Омлет со шпинатом","description":"Пышный омлет с зеленью и свежими томатами. Завтрак за четверть часа.","category":"Завтраки","image":"/images/toast.jpg","time":15,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"egg","quantity":4},{"productId":"milk","quantity":80},{"productId":"spinach","quantity":70},{"productId":"tomato","quantity":120},{"productId":"oil","quantity":7},{"productId":"salt","quantity":1}],"steps":[{"text":"Взбейте яйца с молоком и солью. Помойте шпинат и нарежьте томаты."},{"text":"Прогрейте овощи с маслом, влейте яичную смесь. Готовьте под крышкой до полностью плотной середины.","minutes":9}],"tags":["Без мяса","Без глютена","Быстро","Много белка"],"source":"editorial","version":1}',11);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('yogurt-bowl','{"id":"yogurt-bowl","title":"Йогурт с бананом и ягодами","description":"Прохладный завтрак без плиты. Для утра, когда хочется ещё немного поспать.","category":"Перекусы","image":"/images/oats.jpg","time":5,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"yogurt","quantity":350},{"productId":"banana","quantity":160},{"productId":"berries","quantity":80},{"productId":"oats","quantity":35},{"productId":"honey","quantity":10}],"steps":[{"text":"Нарежьте банан, вымойте ягоды."},{"text":"Разложите йогурт по мискам, добавьте фрукты, хлопья и мёд."}],"tags":["Без мяса","Быстро"],"source":"editorial","version":1}',12);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('baked-apples','{"id":"baked-apples","title":"Яблоки с мёдом и орехами","description":"Тёплый фруктовый десерт с ароматом домашней выпечки.","category":"Десерты","image":"/images/apples.jpg","time":30,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"apple","quantity":400},{"productId":"honey","quantity":25},{"productId":"nuts","quantity":25},{"productId":"butter","quantity":10}],"steps":[{"text":"Удалите сердцевину яблок. Наполните их орехами, мёдом и кусочками масла."},{"text":"Запекайте при 180 °C до мягкости. Дайте немного остыть перед подачей.","minutes":25}],"tags":["Без мяса","Без глютена"],"source":"editorial","version":1}',13);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('zucchini','{"id":"zucchini","title":"Запечённые овощи с фетой","description":"Нежный кабачок, сладкий перец и томаты под лёгкой сырной корочкой.","category":"Гарниры","image":"/images/salad.jpg","time":35,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"zucchini","quantity":350},{"productId":"pepper","quantity":180},{"productId":"tomato","quantity":200},{"productId":"feta","quantity":80},{"productId":"oil","quantity":15},{"productId":"garlic","quantity":5}],"steps":[{"text":"Нарежьте овощи, перемешайте с маслом и чесноком. Выложите в форму."},{"text":"Добавьте фету и запекайте при 190 °C до мягкости овощей.","minutes":28}],"tags":["Без мяса","Без глютена"],"source":"editorial","version":1}',14);
INSERT OR IGNORE INTO recipes(id,data,sort_order) VALUES ('tuna-bowl','{"id":"tuna-bowl","title":"Рисовый боул с тунцом","description":"Свежий, сытный обед с тунцом, авокадо и огурцом.","category":"Ужины","image":"/images/bowl.jpg","time":25,"portions":2,"difficulty":"Легко","ingredients":[{"productId":"rice","quantity":120},{"productId":"tuna","quantity":200},{"productId":"avocado","quantity":100},{"productId":"cucumber","quantity":160},{"productId":"lemon","quantity":20},{"productId":"oil","quantity":8}],"steps":[{"text":"Отварите рис по инструкции на упаковке и слегка остудите.","minutes":18},{"text":"Нарежьте авокадо и огурец. Слейте жидкость с тунца."},{"text":"Соберите боулы, заправьте маслом и лимонным соком."}],"tags":["Без глютена","Без молока","Много белка"],"source":"editorial","version":1}',15);
